for(untagForm of document.getElementsByClassName("untag-form")){untagForm.addEventListener("submit",function(event){event.preventDefault();untag(this);})}
async function untag(untagForm){const data={"recipe":parseInt(untagForm["recipe"].value),"tag_slug":untagForm["tag_slug"].value}
fetch(untagForm.action,{method:"post",headers:{"Content-Type":"application/json","X-CSRFToken":untagForm["csrfmiddlewaretoken"].value,"Accept":"application/json","X-Requested-With":"XMLHttpRequest"},body:JSON.stringify(data)}).then(response=>{return response.json();}).then(responseJSON=>{if(responseJSON.error){const res=createAlert(responseJSON.error,["alert-danger"]);$(`#untag_${untagForm["tag_slug"].value}`).modal("hide");document.getElementById("tag-container").before(res);}else{const res=createAlert(responseJSON.message,["alert-success"]);$(`#untag_${untagForm["tag_slug"].value}`).modal("hide");document.getElementById("tag-container").before(res);document.getElementById(`untag-container_${untagForm["tag_slug"].value}`).remove();}})}
get_all_tags();async function get_all_tags(){fetch("/tags/all/",{method:"get",headers:{"Content-Type":"application/json","Accept":"application/json","X-Requested-With":"XMLHttpRequest",}}).then(response=>{return response.json();}).then(responseJSON=>{if(responseJSON.error){const res=createAlert(responseJSON.error,["alert-danger"]);document.getElementById("id_tags").before(res);}else{tag_list=responseJSON.tag_list;autocomplete(document.getElementById("id_tags"),responseJSON.tag_list);}})}
function search_for_autocomplete(term,options){res=options.filter(s=>s.toLowerCase().search(term.toLowerCase())>-1).sort(s=>s.toLowerCase().search(term.toLowerCase()))
return res}
function autocomplete(inp,arr){var currentFocus;inp.addEventListener("input",function(e){var a,b,i,val;lastComma=this.value.lastIndexOf(",");if(lastComma>-1){val=this.value.slice(lastComma+1).trim()}else{val=this.value}
closeAllLists();if(!val){return false;}
currentFocus=-1;let matches=search_for_autocomplete(val,arr);a=document.createElement("DIV");a.setAttribute("id",this.id+"autocomplete-list");a.setAttribute("class","autocomplete-items");this.parentNode.appendChild(a);matches.map(m=>{b=document.createElement("div");let sub=new RegExp(val,"gi");res=m.replace(sub,(x)=>(`<strong>${x}</strong>`))
b.innerHTML=res;b.innerHTML+=`<input type='hidden' value='${m}'>`;b.addEventListener("click",function(e){selected=this.getElementsByTagName("input")[0].value
lastComma=inp.value.lastIndexOf(",");if(lastComma===-1){inp.value=selected;}else{inp.value=inp.value.slice(0,lastComma)+`, ${selected}`;}
closeAllLists();})
a.appendChild(b);})
x=document.getElementById(this.id+"autocomplete-list");if(x){ac_list=x.getElementsByTagName("div")
currentFocus=0;addActive(ac_list);}});inp.addEventListener("keydown",function(e){var x=document.getElementById(this.id+"autocomplete-list");if(x)x=x.getElementsByTagName("div");if(e.keyCode===40){currentFocus++;addActive(x);}else if(e.keyCode===38){currentFocus--;addActive(x);}else if(e.keyCode===13||e.keyCode===9){e.preventDefault();if(currentFocus>-1){if(x)x[currentFocus].click();}}else if(e.keyCode===188){closeAllLists();}});function addActive(x){if(!x)return false;removeActive(x);if(currentFocus>=x.length)currentFocus=0;if(currentFocus<0)currentFocus=(x.length-1);x[currentFocus].classList.add("autocomplete-active");}
function removeActive(x){for(var i=0;i<x.length;i++){x[i].classList.remove("autocomplete-active");}}
function closeAllLists(elmnt){var x=document.getElementsByClassName("autocomplete-items");for(var i=0;i<x.length;i++){if(elmnt!=x[i]&&elmnt!=inp){x[i].parentNode.removeChild(x[i]);}}}
document.addEventListener("click",function(e){closeAllLists(e.target);});}